TEST(DATA, VALID_F32_MAX) {
    ASSERT_NO_ASSEMBLER_ERROR(
        R"(
            .data
            $x: f32 340282346638528859811704183484516925440
        )"
    );
}

TEST(DATA, VALID_F32_MIN) {
    ASSERT_NO_ASSEMBLER_ERROR(
        R"(
            .data
            $x: f32 -340282346638528859811704183484516925440
        )"
    );
}

TEST(DATA, VALID_F64_MAX) {
    ASSERT_NO_ASSEMBLER_ERROR(
        R"(
            .data
            $x: f64
        )" + std::to_string(std::numeric_limits<double>::max())
    );
}

TEST(DATA, VALID_F64_MIN) {
    ASSERT_NO_ASSEMBLER_ERROR(
        R"(
            .data
            $x: f64
        )" + std::to_string(std::numeric_limits<double>::min())
    );
}

