TEST(DATA, VALID_PTR_LABEL) {
    ASSERT_NO_ASSEMBLER_ERROR(
        R"(
            .data
            $x: ptr $y
            $y: i32 5
        )"
    );
}

TEST(DATA, VALID_STR_STRING) {
    ASSERT_NO_ASSEMBLER_ERROR(
        R"(
            .data
            $str: str "Hello World!"
        )"
    );
}

TEST(DATA, VALID_STR_EMPTY_STRING) {
    ASSERT_NO_ASSEMBLER_ERROR(
        R"(
            .data
            $str: str ""
        )"
    );
}

